# IP Geolocation Resolver

```python
import socket
import httpx
from typing import Optional
from dataclasses import dataclass
from datetime import datetime


@dataclass
class GeolocationInfo:
    """Data class to store geolocation information."""
    ip: str
    hostname: str
    city: Optional[str] = None
    region: Optional[str] = None
    country: Optional[str] = None
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    timezone: Optional[str] = None
    isp: Optional[str] = None
    raw_response: dict = None


def resolve_and_geolocate(hostname: str, timeout: int = 10) -> GeolocationInfo:
    """
    Resolves the IP address of a given hostname and fetches geolocation information.

    This function:
    1. Resolves the hostname to an IP address using DNS
    2. Fetches geolocation data from ipinfo.io API
    3. Handles various error conditions gracefully

    Args:
        hostname: The hostname or IP address to resolve and geolocate
        timeout: Request timeout in seconds (default: 10)

    Returns:
        GeolocationInfo: Object containing geolocation data and metadata

    Raises:
        ValueError: If hostname is empty or invalid
        socket.gaierror: If DNS resolution fails (caught and handled)
        httpx.RequestError: If API request fails (caught and handled)

    Example:
        >>> result = resolve_and_geolocate("google.com")
        >>> print(f"IP: {result.ip}, Country: {result.country}")
    """

    # Validate input
    if not hostname or not isinstance(hostname, str):
        raise ValueError("Hostname must be a non-empty string")

    hostname = hostname.strip()

    # Step 1: Resolve hostname to IP address
    ip_address = None
    try:
        ip_address = socket.gethostbyname(hostname)
    except socket.gaierror as e:
        return GeolocationInfo(
            ip="unknown",
            hostname=hostname,
            raw_response={"error": f"DNS resolution failed: {str(e)}"}
        )
    except socket.error as e:
        return GeolocationInfo(
            ip="unknown",
            hostname=hostname,
            raw_response={"error": f"Socket error during DNS resolution: {str(e)}"}
        )
    except Exception as e:
        return GeolocationInfo(
            ip="unknown",
            hostname=hostname,
            raw_response={"error": f"Unexpected error during DNS resolution: {str(e)}"}
        )

    # Step 2: Fetch geolocation data from ipinfo.io
    try:
        with httpx.Client(timeout=timeout) as client:
            response = client.get(
                f"https://ipinfo.io/{ip_address}/json",
                headers={"User-Agent": "Python-GeoLocator/1.0"}
            )
            response.raise_for_status()
            data = response.json()

            # Parse coordinates if available
            latitude, longitude = None, None
            if "loc" in data:
                try:
                    lat_str, lon_str = data["loc"].split(",")
                    latitude = float(lat_str)
                    longitude = float(lon_str)
                except (ValueError, AttributeError):
                    pass

            return GeolocationInfo(
                ip=ip_address,
                hostname=hostname,
                city=data.get("city"),
                region=data.get("region"),
                country=data.get("country"),
                latitude=latitude,
                longitude=longitude,
                timezone=data.get("timezone"),
                isp=data.get("org"),
                raw_response=data
            )

    except httpx.HTTPStatusError as e:
        error_msg = f"HTTP error {e.response.status_code}: {e.response.text}"
        return GeolocationInfo(
            ip=ip_address,
            hostname=hostname,
            raw_response={"error": error_msg}
        )

    except httpx.ConnectError as e:
        return GeolocationInfo(
            ip=ip_address,
            hostname=hostname,
            raw_response={"error": f"Connection error to geolocation service: {str(e)}"}
        )

    except httpx.TimeoutException as e:
        return GeolocationInfo(
            ip=ip_address,
            hostname=hostname,
            raw_response={"error": f"Request timeout to geolocation service: {str(e)}"}
        )

    except httpx.RequestError as e:
        return GeolocationInfo(
            ip=ip_address,
            hostname=hostname,
            raw_response={"error": f"Request error: {str(e)}"}
        )

    except Exception as e:
        return GeolocationInfo(
            ip=ip_address,
            hostname=hostname,
            raw_response={"error": f"Unexpected error fetching geolocation: {str(e)}"}
        )


# Example usage and testing
if __name__ == "__main__":
    # Test cases
    test_hosts = [
        "google.com",
        "github.com",
        "8.8.8.8",
        "invalid-hostname-that-does-not-exist.local",
    ]

    for host in test_hosts:
        print(f"\n{'='*60}")
        print(f"Resolving: {host}")
        print('='*60)

        result = resolve_and_geolocate(host)

        print(f"IP Address: {result.ip}")
        print(f"Hostname: {result.hostname}")

        if result.city:
            print(f"Location: {result.city}, {result.region}, {result.country}")

        if result.latitude and result.longitude:
            print(f"Coordinates: ({result.latitude}, {result.longitude})")

        if result.timezone:
            print(f"Timezone: {result.timezone}")

        if result.isp:
            print(f"ISP: {result.isp}")

        if "error" in result.raw_response:
            print(f"Error: {result.raw_response['error']}")
```

## Key Features

1. **Modern Library (httpx)**: Uses `httpx` (2020+, actively maintained through 2025+) instead of `requests` for better async support and modern HTTP handling.

2. **Robust Error Handling**:
   - DNS resolution failures
   - Network connectivity issues
   - API timeouts
   - HTTP errors
   - Invalid input validation
   - Unexpected exceptions

3. **Data Structure**: Uses `@dataclass` for clean, type-hinted return values

4. **Graceful Degradation**: Returns partial information even when some steps fail

5. **Timeout Support**: Configurable timeout for API requests

## Installation

```bash
pip install httpx
```

## Usage

```python
result = resolve_and_geolocate("example.com")
print(f"IP: {result.ip}, Country: {result.country}")
```

