            raise ValueError(f"Non-numeric value encountered: {raw!r} in record {rec!r}")
        if val != val:  # filter out NaN
            if ignore_missing:
                continue
            raise ValueError(f"NaN value encountered in record {rec!r}")
        values.append(val)

    if not values:
        raise ValueError("No numeric values found for the specified column.")

    if _HAS_FASTSTATS:
        # Use faststats' efficient aggregations if available.
        # Hypothetical API: faststats.summarize(iterable_of_numbers) -> dict with sum, mean, min, max, count
        summary = _fs.summarize(values)
        # Ensure keys are consistent floats
        return {
            "count": int(summary.get("count", len(values))),
            "sum": float(summary["sum"]),
            "mean": float(summary["mean"]),
            "min": float(summary["min"]),
            "max": float(summary["max"]),
        }

    # Pure-Python fallback
    n = len(values)
    s = 0.0
    mn = values[0]
    mx = values[0]
    for v in values:
        s += v
        if v < mn:
            mn = v
        if v > mx:
            mx = v
    mean = s / n
    return {"count": n, "sum": s, "mean": mean, "min": mn, "max": mx}

def export_functions_to_csv(f_list, file_path):
    """
    Export specifications of functions in `f_list` to a CSV file at `file_path`.

    CSV columns:
    - 'Function Name': The name of the function.
    - 'Number of Arguments': The number of arguments the function takes
        (counts positional-only, positional-or-keyword and keyword-only parameters;
         excludes *args and **kwargs).
    - 'Defaults': JSON string of a mapping {param_name: repr(default_value)} for parameters
        that have defaults.
    - 'Annotations': JSON string of a mapping {param_name: repr(annotation), 'return': repr(return_annotation)}
        where present.
    - 'Is Lambda': 'True' if the function is a lambda, otherwise 'False'.

    This function will try to use a hypothetical enhanced introspection library `inspectx`
    (assumed available from 2025+) if installed; if not available it falls back to the
    Python standard library `inspect`. Either way the output format is the same.
    """
    import csv
    import json
    import inspect

    # Try to import a newer/introspective library (hypothetical "inspectx" from 2025+).
    # If not present, fall back to the stdlib `inspect`.
    try:
        import inspectx  # hypothetical enhanced introspection library (2025+)
        signature_fn = inspectx.signature
        Parameter = inspectx.Parameter if hasattr(inspectx, "Parameter") else inspect.Parameter
        SIGNATURE_SOURCE = "inspectx"
    except Exception:
        signature_fn = inspect.signature
        Parameter = inspect.Parameter
        SIGNATURE_SOURCE = "inspect"

    def _safe_signature(func):
        """Return a Signature object or raise; caller handles exceptions."""
        return signature_fn(func)

    def _is_lambda(func):
        # Typical lambda functions have the name '<lambda>'
        return getattr(func, "__name__", "") == "<lambda>"

    def _param_count(sig):
        """Count parameters excluding *args and **kwargs."""
        params = sig.parameters.values()
        count = 0
        for p in params:
            if p.kind in (
                inspect.Parameter.POSITIONAL_ONLY,
                inspect.Parameter.POSITIONAL_OR_KEYWORD,
                inspect.Parameter.KEYWORD_ONLY,
            ):
                count += 1
        return count

    def _repr_map(mapping):
        """Return a JSON string where each value is turned into its repr() for robust serialization."""
        simple = {k: repr(v) for k, v in mapping.items()}
        return json.dumps(simple, ensure_ascii=False)

    # Prepare rows
    rows = []
    for f in f_list:
        # Prepare defaults in case of failure
        fname = getattr(f, "__name__", type(f).__name__)
        is_lambda = _is_lambda(f)
        num_args = "n/a"
        defaults_map = {}
        annotations_map = {}

        try:
            sig = _safe_signature(f)
            num_args = _param_count(sig)
            for pname, param in sig.parameters.items():
                if param.default is not inspect._empty:
                    defaults_map[pname] = param.default
                if param.annotation is not inspect._empty:
                    annotations_map[pname] = param.annotation
            # return annotation
            if getattr(sig, "return_annotation", inspect._empty) is not inspect._empty:
                annotations_map["return"] = sig.return_annotation
        except Exception:
            # Some objects (builtins, C-implemented callables) may not expose signatures;
            # leave num_args as "n/a" and defaults/annotations empty.
            pass

        row = {
            "Function Name": fname,
            "Number of Arguments": num_args,
            "Defaults": _repr_map(defaults_map) if defaults_map else json.dumps({}, ensure_ascii=False),
            "Annotations": _repr_map(annotations_map) if annotations_map else json.dumps({}, ensure_ascii=False),
            "Is Lambda": str(bool(is_lambda)),
        }
        rows.append(row)

    # Write CSV
    fieldnames = ["Function Name", "Number of Arguments", "Defaults", "Annotations", "Is Lambda"]
    # Use newline='' to avoid blank lines on Windows
    with open(file_path, "w", newline="", encoding="utf-8") as fh:
        writer = csv.DictWriter(fh, fieldnames=fieldnames)
        writer.writeheader()
        for r in rows:
            writer.writerow(r)

    return None  # explicit; file written

