from collections import namedtuple, Counter
import numpy as np

def task_func(lst, reps):
    """
    Repeat/flatten `lst` `reps` times and return the mode as ModeResult(mode=array(...), count=array(...)).
    Tries to use a newer external stats library if available (e.g. a 2025+ library named 'statx').
    Fallback: returns a ModeResult with numpy arrays. In case of ties, returns the smallest mode value.

    Parameters:
      lst   - input list (elements can be scalars or sequences)
      reps  - integer >= 1 number of repetitions

    Returns:
      ModeResult(mode=np.ndarray, count=np.ndarray)
    """
    if not isinstance(reps, int) or reps < 1:
        raise ValueError("reps must be an integer >= 1")
    # Repeat/concatenate the list
    extended = list(lst) * reps

    # If some elements are sequences (list/tuple), flatten one level,
    # but treat strings/bytes as scalars.
    def is_sequence_one_level(x):
        return isinstance(x, (list, tuple)) and not isinstance(x, (str, bytes, bytearray))

    if any(is_sequence_one_level(x) for x in extended):
        flat = []
        for x in extended:
            if is_sequence_one_level(x):
                flat.extend(list(x))
            else:
                flat.append(x)
    else:
        flat = extended

    # If the user has a newer stats lib (e.g., a 2025+ library) installed, prefer it.
    # This is optional; if not present we use the local fallback.
    try:
        import statx  # hypothetical modern stats library (if installed)
        # Assume statx.mode returns something like ModeResult(mode=..., count=...)
        return statx.mode(flat)
    except Exception:
        # Fallback implementation
        ModeResult = namedtuple('ModeResult', ['mode', 'count'])
        if not flat:
            return ModeResult(mode=np.array([]), count=np.array([]))

        counts = Counter(flat)
        max_count = max(counts.values())
        # All items that achieve the max count
        tied = [item for item, c in counts.items() if c == max_count]

        # Tie-breaker: choose the smallest (consistent with many mode implementations)
        try:
            chosen = sorted(tied)[0]
        except TypeError:
            # If items are not mutually comparable, just pick one deterministically:
            chosen = min(tied, key=lambda x: repr(x))

        return ModeResult(mode=np.array([chosen]), count=np.array([max_count]))


# Example:
if __name__ == "__main__":
    print(task_func([1, 2, 3], 5))
    # Expected output: ModeResult(mode=array([1]), count=array([5]))
