Code:

```python
from collections import Counter
from typing import Any, List

def mode_of_nested_list(L: Any) -> List[Any]:
    """
    Compute the mode(s) of all elements inside a nested list-like structure L.
    - Traverses nested lists/tuples.
    - Normalizes unhashable containers (lists, dicts, sets, tuples) into hashable forms
      so they can be counted, while preserving a mapping back to the first-seen original object.
    - Returns a list of the most frequent original elements (could be multiple if tied).
    - Returns an empty list for empty input/when no leaves are found.
    """
    def normalize(x):
        # Normalize container types into hashable, comparable tuples
        if isinstance(x, (list, tuple)):
            return ('__list__', tuple(normalize(e) for e in x))
        if isinstance(x, dict):
            # sort items by key to canonicalize
            return ('__dict__', tuple((k, normalize(v)) for k, v in sorted(x.items(), key=lambda kv: kv[0])))
        if isinstance(x, (set, frozenset)):
            return ('__set__', tuple(sorted(normalize(e) for e in x)))
        # primitives / other objects: assume already hashable
        return ('__val__', x)

    # Flattening traversal: depth-first
    stack = [L]
    counts = Counter()
    norm_to_original = {}
    while stack:
        item = stack.pop()
        if isinstance(item, (list, tuple)):
            # push elements to traverse deeper
            for e in item:
                stack.append(e)
        else:
            # treat as a leaf element (including dicts/sets, which we consider leaves to be normalized)
            n = normalize(item)
            counts[n] += 1
            # store first-seen original element for this normalized key
            if n not in norm_to_original:
                norm_to_original[n] = item

    if not counts:
        return []
    maxcount = max(counts.values())
    modes_norm = [k for k, v in counts.items() if v == maxcount]
    return [norm_to_original[n] for n in modes_norm]

# Example usage:
if __name__ == "__main__":
    L = [1, [2, 3, [1, 2]], [1, [2, {'a': 5}], (2, 3)], {'a': 5}]
    print(mode_of_nested_list(L))  # might output [1, 2] if 1 and 2 tie for top frequency
```

