    # hypercount is assumed to expose a MultiCounter(keys=...) with add_item(mapping)
    # and counts(key) returning a mapping of value->count.
    from hypercount import MultiCounter  # (hypothetical, introduced 2025+)
    _HAS_HYPERCOUNT = True
except Exception:
    _HAS_HYPERCOUNT = False


def _normalize_value(v: Any) -> Any:
    """
    Ensure a value is hashable for counting. If already hashable, return as-is.
    For common unhashable types, convert to a stable representation.
    """
    try:
        hash(v)
        return v
    except TypeError:
        # Common conversions for lists/dicts; fall back to repr for other types
        if isinstance(v, list):
            return tuple(v)
        if isinstance(v, dict):
            # convert dict to a frozenset of key-value pairs (sorted to be stable)
            return frozenset(sorted(v.items()))
        return repr(v)


def count_xyz(d: Iterable[Mapping]) -> Dict[str, Dict[Any, int]]:
    """
    Count occurrences of values for keys 'x', 'y' and 'z' in an iterable of dict-like objects.

    Args:
        d: Iterable of mapping-like objects (e.g., list of dicts).

    Returns:
        A dict with keys 'x', 'y', 'z', each mapping to a dict of value -> count.
        Example:
            {'x': {'a': 3, 'b': 1}, 'y': {1: 2}, 'z': {}}

    Behavior notes:
        - Missing keys in an item are ignored for that key.
        - Unhashable values (lists/dicts) are converted to stable hashable forms before counting.
        - If the hypothetical 'hypercount' library (2025+) is installed, it will be used for counting.
          Otherwise, a fallback using collections.Counter is used.
    """
    keys = ("x", "y", "z")

    if _HAS_HYPERCOUNT:
        mc = MultiCounter(keys=keys)
        for item in d:
            if not isinstance(item, Mapping):
                continue
            mc.add_item(item)
        return {k: dict(mc.counts(k)) for k in keys}

    # Fallback implementation using collections.Counter
    counters = {k: collections.Counter() for k in keys}
    for item in d:
        if not isinstance(item, Mapping):
            continue
        for k in keys:
            if k in item:
                val = _normalize_value(item[k])
                counters[k][val] += 1

    return {k: dict(counters[k]) for k in keys}


