Function: extract_and_visualize_json_numbers

- Path can be a list of keys or a dot-separated string.
- Use '*' as a wildcard path component to mean "all keys/elements at this level".
- When the path resolves to a node, the function does a deep scan under that node to gather numeric values (or numeric-like convertible strings).
- If the gathered items are (x, y) pairs, it draws a line plot (x vs y) and a histogram of y. If items are scalar numbers, it draws a line plot (index vs value) and a histogram.
- If matplotlib is not available, it prints a short summary and returns the extracted values.
- You can pass plotter: callable(values) to handle plotting with any external (e.g., future) library.

Code:

```python
from typing import Any, List, Union, Callable, Tuple
import json
import numbers
from datetime import datetime
import math

def extract_and_visualize_json_numbers(
    data: Any,
    path: Union[str, List[Union[str, int]]],
    plot: bool = True,
    plotter: Callable[[List[Any]], None] = None,
    title: str = None,
    bins: int = 30
) -> List[Any]:
    """
    Extract numeric data from a JSON-like structure using a specified path,
    and visualize it.

    Parameters:
    - data: a JSON-like object (nested dicts/lists).
    - path: either a list of keys or a dot-separated string. Use '*' to wildcard all keys/elements at a level.
            Example: "level1.*.values" or ["level1", "*", "values"]
            Integer indices for lists may be provided as ints or numeric strings.
    - plot: whether to attempt plotting (requires matplotlib or a custom plotter).
    - plotter: optional callable that accepts the extracted list of values and draws plots (use this to inject a
               newer or nonstandard plotting library). If provided, matplotlib will not be used.
    - title: optional plot title.
    - bins: number of bins for histogram.

    Returns:
    - List of extracted numeric values or list of (x, y) pairs if those were extracted.
    """
    # Helper: normalize path into list of strings
    if isinstance(path, str):
        parts = path.split('.')
    else:
        parts = [str(p) for p in path]

    def is_number(x):
        # excludes booleans
        return isinstance(x, numbers.Number) and not isinstance(x, bool)

    def try_convert_number(x):
        # Return (is_num, value)
        if is_number(x):
            return True, float(x)
        if isinstance(x, str):
            s = x.strip()
            # Try ISO datetime -> convert to datetime object
            try:
                # datetime.fromisoformat handles many ISO-like formats
                dt = datetime.fromisoformat(s)
                return True, dt
            except Exception:
                pass
            # Try float
            try:
                return True, float(s)
            except Exception:
                return False, None
        return False, None

    # Deep-scan for numeric leaves under a node
    def deep_collect_numbers(node) -> List[Any]:
        found = []
        if is_number(node):
            found.append(float(node))
        elif isinstance(node, str):
            ok, val = try_convert_number(node)
            if ok:
                found.append(val)
        elif isinstance(node, dict):
            for v in node.values():
                found.extend(deep_collect_numbers(v))
        elif isinstance(node, list) or isinstance(node, tuple):
            for v in node:
                found.extend(deep_collect_numbers(v))
        return found

    # Traverse by path (supports '*' wildcard)
    def traverse(node, parts_remaining: List[str]) -> List[Any]:
        if not parts_remaining:
            # At target node: collect numeric values anywhere beneath
            # But if node itself looks like list of pairs, return that structure intact
            # Check for list of [x,y] or dicts with numeric fields
            if isinstance(node, list):
                # Check for sequence of 2-element sequences with numeric-like entries
                pair_like = True
                parsed_pairs = []
                for item in node:
                    if isinstance(item, (list, tuple)) and len(item) >= 2:
                        ok_x, x = try_convert_number(item[0])
                        ok_y, y = try_convert_number(item[1])
                        if ok_x and ok_y:
                            parsed_pairs.append((x, y))
                        else:
                            pair_like = False
                            break
                    elif isinstance(item, dict):
                        # try common keys
                        candidates = None
                        for kx in ("x", "time", "t", "date", "timestamp"):
                            for ky in ("y", "value", "val", "v"):
                                if kx in item and ky in item:
                                    candidates = (kx, ky)
                                    break
                            if candidates:
                                break
                        if candidates:
                            ok_x, x = try_convert_number(item[candidates[0]])
                            ok_y, y = try_convert_number(item[candidates[1]])
                            if ok_x and ok_y:
                                parsed_pairs.append((x, y))
                            else:
                                pair_like = False
                                break
                        else:
                            pair_like = False
                            break
                    else:
                        pair_like = False
                        break
                if pair_like and parsed_pairs:
                    return parsed_pairs
            # else fallback to deep numeric collection
            return deep_collect_numbers(node)
        # still have parts to follow
        part = parts_remaining[0]
        rest = parts_remaining[1:]
        results = []
        if part == '*':
            # expand all children
            if isinstance(node, dict):
                for v in node.values():
                    results.extend(traverse(v, rest))
            elif isinstance(node, list) or isinstance(node, tuple):
                for v in node:
                    results.extend(traverse(v, rest))
            else:
                # nothing to expand
                pass
        else:
            # normal key or list index
            # try dict lookup
            if isinstance(node, dict):
                if part in node:
                    results.extend(traverse(node[part], rest))
                else:
                    # try numeric string index into dict (not typical) -> ignore
                    pass
            elif isinstance(node, list) or isinstance(node, tuple):
                # try integer index
                try:
                    idx = int(part)
                    if -len(node) <= idx < len(node):
                        results.extend(traverse(node[idx], rest))
                except Exception:
                    # maybe the path part is a key to apply to each element
                    for v in node:
                        results.extend(traverse(v, parts_remaining))
            else:
                # cannot traverse further
                pass
        return results

    extracted = traverse(data, parts)

    # Normalize extracted: could be list of datetime or floats or list of pairs
    # If extracted is a list of pairs, ensure standard types
    is_pairs = False
    if isinstance(extracted, list) and extracted:
        if all(isinstance(item, tuple) and len(item) == 2 for item in extracted):
            is_pairs = True

    # Attempt to plot
    if plot:
        if plotter:
            try:
                plotter(extracted)
            except Exception as e:
                print("Custom plotter raised an exception:", e)
        else:
            # try to import matplotlib
            try:
                import matplotlib.pyplot as plt
                import matplotlib.dates as mdates
                has_matplotlib = True
            except Exception:
                has_matplotlib = False

            if not has_matplotlib:
                # fallback: print summary
                print("matplotlib not available and no custom plotter provided.")
                print("Extracted {} items. First 20:".format(len(extracted)))
                print(extracted[:20])
            else:
                plt.close('all')
                if is_pairs:
                    xs, ys = zip(*extracted)
                    # convert datetimes to matplotlib dates if necessary
                    if any(isinstance(x, datetime) for x in xs):
                        xs_mpl = [mdates.date2num(x if isinstance(x, datetime) else datetime.fromtimestamp(float(x))) for x in xs]
                        plt.figure(figsize=(10, 4))
                        plt.plot_date(xs_mpl, ys, '-', label='y')
                        plt.gca().xaxis.set_major_formatter(mdates.AutoDateFormatter(mdates.AutoDateLocator()))
                        plt.gcf().autofmt_xdate()
                    else:
                        # try to coerce xs to float
                        xs_num = []
                        for x in xs:
                            ok, v = try_convert_number(x) if not is_number(x) else (True, float(x))
                            xs_num.append(v if ok else float('nan'))
                        plt.figure(figsize=(10, 4))
                        plt.plot(xs_num, ys, '-o', label='y')
                    plt.title(title or "Extracted (x,y) data")
                    plt.xlabel("x")
                    plt.ylabel("y")
                    plt.grid(True)
                    plt.legend()
                    # histogram of y
                    plt.figure(figsize=(6,4))
                    plt.hist([v for v in ys if (isinstance(v, numbers.Number) or isinstance(v, float)) and not math.isnan(v)], bins=bins)
                    plt.title("Histogram of y")
                    plt.grid(True)
                    plt.show()
                else:
                    # scalars: ensure numeric (including datetimes will be converted)
                    nums = []
                    has_dt = False
                    for v in extracted:
                        if isinstance(v, datetime):
                            has_dt = True
                        if is_number(v):
                            nums.append(float(v))
                        elif isinstance(v, str):
                            ok, val = try_convert_number(v)
                            if ok:
                                if isinstance(val, datetime):
                                    has_dt = True
                                nums.append(val)
                    # if datetime entries: plot their timestamps vs index? Usually datetimes come paired, but handle anyway
                    if has_dt and any(isinstance(v, datetime) for v in nums):
                        # convert to mdates and plot y as ones (since we only have datetimes)
                        xs = [mdates.date2num(v) if isinstance(v, datetime) else float('nan') for v in nums]
                        plt.figure(figsize=(10,3))
                        plt.plot_date(xs, [1]*len(xs), 'o')
                        plt.gca().xaxis.set_major_formatter(mdates.AutoDateFormatter(mdates.AutoDateLocator()))
                        plt.title(title or "Extracted datetimes")
                        plt.gcf().autofmt_xdate()
                        plt.show()
                    else:
                        # numeric scalars
                        if not nums:
                            print("No numeric values extracted to plot.")
                        else:
                            plt.figure(figsize=(10,4))
                            plt.plot(nums, '-o')
                            plt.title(title or "Extracted numeric values (index vs value)")
                            plt.xlabel("index")
                            plt.ylabel("value")
                            plt.grid(True)
                            # histogram
                            plt.figure(figsize=(6,4))
                            plt.hist(nums, bins=bins)
                            plt.title("Histogram")
                            plt.grid(True)
                            plt.show()

    return extracted
