# print(weights_kg)
```

Notes:
- The weight parser uses heuristics to cover many common real-world string formats; it may not be perfect for every edge case, but returns np.nan when it cannot robustly interpret a string.
- Replace "neoviz" with your actual 2025+ plotting library name if you have a specific new library installed; the function is structured to prefer such a library while remaining functional without it.

Below is a single self-contained Python function that fetches a webpage, extracts the contents of all <script> tags, and tries to evaluate each script text as a Python dictionary. It attempts several safe parsing strategies (ast.literal_eval, JSON, json5 if available, and a best-effort JS->JSON cleaning). It will try to use an optional hypothetical "new" fetch/parser library (fetchx2025) if present; otherwise it falls back to standard/httpx and stdlib HTML parsing. The function never uses Python's eval() — it uses safe literal evaluation only.

Note: The "fetchx2025" import is optional and illustrative of a "new library (2025+)"; if you don't have it the code falls back to well-known libs or the stdlib. If you want json5 support for JS-style objects, pip install "python-json5".

Code:

```python
from typing import List, Dict, Any, Optional
import ast
import json
import re

# Try to import a hypothetical modern library introduced in 2025 (optional).
# If not present, we'll fall back to httpx + stdlib parsing.
try:
    import fetchx2025 as _fetchlib  # optional: a "new" library (2025+). If absent, fallback is used.
    _HAS_NEWLIB = True
except Exception:
    _fetchlib = None
    _HAS_NEWLIB = False

# Try to import httpx (widely used). If unavailable, fallback to urllib.
try:
    import httpx
    _HAS_HTTPX = True
except Exception:
    import urllib.request
    _HAS_HTTPX = False

# Try to import json5 (optional) to parse JS-like objects (unquoted keys, trailing commas).
try:
    import json5
    _HAS_JSON5 = True
except Exception:
    json5 = None
    _HAS_JSON5 = False

# We'll use stdlib HTML parser to avoid external HTML deps (self-contained).
from html.parser import HTMLParser


class _ScriptExtractor(HTMLParser):
    """Simple HTMLParser-based extractor that returns contents of all <script> tags."""
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self._in_script = False
        self._buf = []
        self.scripts = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "script":
            self._in_script = True
            self._buf = []

    def handle_endtag(self, tag):
        if tag.lower() == "script" and self._in_script:
            # join and store
            self.scripts.append("".join(self._buf))
            self._in_script = False
            self._buf = []

    def handle_data(self, data):
        if self._in_script:
            self._buf.append(data)

    def handle_comment(self, data):
        # comments inside script are also data; include them
        if self._in_script:
            self._buf.append("<!--" + data + "-->")


def _find_balanced_brace_segment(s: str) -> Optional[str]:
    """
    Find the first balanced {...} segment in s, return it including braces.
    This is a best-effort that handles quotes and escapes (single/double).
    """
    start = s.find("{")
    if start == -1:
        return None
    depth = 0
    i = start
    in_string = False
    string_char = ""
    escape = False
    while i < len(s):
        ch = s[i]
        if in_string:
            if escape:
                escape = False
            elif ch == "\\":
                escape = True
            elif ch == string_char:
                in_string = False
        else:
            if ch == '"' or ch == "'":
                in_string = True
                string_char = ch
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    return s[start:i+1]
        i += 1
    return None


def _js_to_json_like(s: str) -> str:
    """
    Best-effort transform of a JS object-like string into JSON:
      - remove JS-style trailing commas
      - attempt to quote unquoted keys with a regex (best-effort)
    Note: This is heuristic and may not work on complex JS objects.
    """
    # Remove JavaScript comments (//... and /* ... */)
    s = re.sub(r"//.*?$", "", s, flags=re.MULTILINE)
    s = re.sub(r"/\*.*?\*/", "", s, flags=re.DOTALL)

    # Remove leading "var foo = " or "const foo =" or "let foo =" and trailing semicolons
    s = re.sub(r'^\s*(?:var|let|const)\s+[A-Za-z0-9_$]+\s*=\s*', '', s)
    s = s.strip()
    # Remove trailing semicolon
    if s.endswith(";"):
        s = s[:-1]

    # Best-effort: quote unquoted keys:  foo: -> "foo":
    # Only matches keys that are valid JS identifier tokens (no dots)
    def _quote_key(match):
        return f'"{match.group(1)}":'

    s = re.sub(r'([A-Za-z_][A-Za-z0-9_]*)\s*:', _quote_key, s)

    # Remove trailing commas before } or ]
    s = re.sub(r',\s*(?=[}\]])', '', s)

    return s


def fetch_script_dicts(url: str, timeout: float = 10.0) -> List[Dict[str, Any]]:
    """
    Fetches the webpage at `url`, finds all <script> tag contents, and attempts to evaluate each script block
    as a Python dictionary (safely). Returns a list of result dicts, each with:
      - index: int, index of the script tag (0-based)
      - text: str, the raw script text (trimmed)
      - success: bool, whether parsing produced a dict
      - value: dict or None, the resulting dict if success
      - error: Optional[str], a short error message if parsing failed

    The function uses only safe parsing (ast.literal_eval, json.loads, json5 if available) and never calls eval().
    """
    # 1) Fetch HTML
    if _HAS_NEWLIB and _fetchlib is not None:
        # hypothetical new library usage (optional)
        resp = _fetchlib.get(url, timeout=timeout)
        html = resp.text
    else:
        if _HAS_HTTPX:
            resp = httpx.get(url, timeout=timeout)
            resp.raise_for_status()
            html = resp.text
        else:
            with urllib.request.urlopen(url, timeout=timeout) as resp:
                html = resp.read().decode(resp.headers.get_content_charset("utf-8"))

    # 2) Extract scripts
    parser = _ScriptExtractor()
    parser.feed(html)
    scripts = parser.scripts

    results: List[Dict[str, Any]] = []

    for idx, raw in enumerate(scripts):
        txt = raw.strip()
        if not txt:
            results.append({"index": idx, "text": txt, "success": False, "value": None, "error": "empty"})
            continue

        # Remove HTML comment wrappers sometimes used inside scripts: <!-- ... -->
        txt = re.sub(r"^\s*<!--\s*", "", txt)
        txt = re.sub(r"\s*-->\s*$", "", txt)

        parsed = None
        last_err = None

        # Try several strategies in order (safe)
        # Strategy A: ast.literal_eval directly (works if script contains a Python literal dict)
        try:
            obj = ast.literal_eval(txt)
            if isinstance(obj, dict):
                parsed = obj
            else:
                last_err = f"literal_eval produced non-dict type {type(obj).__name__}"
        except Exception as e:
            last_err = f"literal_eval: {e}"

        # Strategy B: JSON
        if parsed is None:
            try:
                obj = json.loads(txt)
                if isinstance(obj, dict):
                    parsed = obj
                else:
                    last_err = f"json.loads produced non-dict type {type(obj).__name__}"
            except Exception as e:
                last_err = f"json.loads: {e}"

        # Strategy C: json5 (if available) - accepts JS-style objects
        if parsed is None and _HAS_JSON5:
            try:
                obj = json5.loads(txt)
                if isinstance(obj, dict):
                    parsed = obj
                else:
                    last_err = f"json5.loads produced non-dict type {type(obj).__name__}"
            except Exception as e:
                last_err = f"json5.loads: {e}"

        # Strategy D: try to extract first {...} balanced segment and parse that
        if parsed is None:
            seg = _find_balanced_brace_segment(txt)
            if seg is not None:
                # try ast
                try:
                    obj = ast.literal_eval(seg)
                    if isinstance(obj, dict):
                        parsed = obj
                    else:
                        last_err = f"brace+literal_eval produced non-dict {type(obj).__name__}"
                except Exception as e:
                    last_err = f"brace+literal_eval: {e}"
                if parsed is None:
                    try:
                        obj = json.loads(seg)
                        if isinstance(obj, dict):
                            parsed = obj
                        else:
                            last_err = f"brace+json.loads produced non-dict {type(obj).__name__}"
                    except Exception as e:
                        last_err = f"brace+json.loads: {e}"
                if parsed is None and _HAS_JSON5:
                    try:
                        obj = json5.loads(seg)
                        if isinstance(obj, dict):
                            parsed = obj
                        else:
                            last_err = f"brace+json5 produced non-dict {type(obj).__name__}"
                    except Exception as e:
                        last_err = f"brace+json5: {e}"

        # Strategy E: best-effort JS->JSON transforms then parse
        if parsed is None:
            try:
                cleaned = _js_to_json_like(txt)
                obj = json.loads(cleaned)
                if isinstance(obj, dict):
                    parsed = obj
                else:
                    last_err = f"js_to_json->json.loads produced non-dict {type(obj).__name__}"
            except Exception as e:
                last_err = f"js_to_json->json.loads: {e}"
                # If json5 present, try it on cleaned text
                if _HAS_JSON5:
                    try:
                        obj = json5.loads(cleaned)
                        if isinstance(obj, dict):
                            parsed = obj
                        else:
                            last_err = f"js_to_json->json5 produced non-dict {type(obj).__name__}"
                    except Exception as e2:
                        last_err = f"js_to_json->json5: {e2}"

        results.append({
            "index": idx,
            "text": txt,
            "success": parsed is not None,
            "value": parsed,
            "error": None if parsed is not None else last_err
        })

    return results
```

Usage example:
- Call fetch_script_dicts("https://example.com")
- Inspect returned list — each entry indicates success and contains the parsed dict if successful.

Security note:
- This code does not use eval() or execute script contents; it only uses safe literal parsing functions and JSON parsers. The attempted JS->JSON heuristics are best-effort and may fail on complex scripts. If you need higher fidelity parsing of arbitrary JS, consider using a JS runtime (e.g., Node) to evaluate or a robust JS parser library.

Below is a self-contained Python function that converts a Unix timestamp to a formatted date/time string in a specified timezone. It demonstrates use of a hypothetical "new" timezone-aware library (named chronox in the code) if it is installed (as you requested a 2025+ library), and otherwise falls back to the Python standard library (zoneinfo + datetime). I clearly mark the chronox usage as optional/hypothetical — if you do have a real 2025+ library, you can replace "chronox" usage with that library's API or install chronox if it exists.

Function features:
- Accepts seconds or milliseconds (auto-detected).
- Accepts a TZ name like "Europe/Berlin" or "UTC".
- Customizable format string (defaults to "%Y-%m-%d %H:%M:%S %Z%z").
- Raises ValueError for invalid timezone names.

Code:

```python
from __future__ import annotations
from typing import Union
import importlib
from datetime import datetime, timezone
try:
    # zoneinfo is available in Python 3.9+
    from zoneinfo import ZoneInfo
except Exception:
    ZoneInfo = None  # we'll handle this later


def unix_timestamp_to_tz_string(
    ts: Union[int, float],
    tz_name: str = "UTC",
    fmt: str = "%Y-%m-%d %H:%M:%S %Z%z",
) -> str:
    """
    Convert a Unix timestamp to a formatted date/time string in the given timezone.

    Parameters:
    - ts: Unix timestamp (seconds or milliseconds). The function will auto-detect
          millisecond timestamps if ts > 1e12 (approx year 33658) or > 1e11 (safer).
    - tz_name: IANA timezone name, e.g. "UTC", "Europe/Berlin", "America/New_York".
    - fmt: strftime-style format string. Default includes timezone abbreviation and offset.

    Behavior:
    - If a (hypothetical) newer library named 'chronox' is installed, the function will
      attempt to use it for conversion. This branch is optional and illustrative;
      if chronox is not available, the function falls back to the Python standard library.
    - Raises ValueError if the timezone name is invalid or cannot be resolved.

    Returns:
    - Formatted date/time string.
    """

    # Auto-detect milliseconds vs seconds:
    # If timestamp looks like milliseconds (e.g. > 1e11), convert to seconds.
    ts_val = float(ts)
    if abs(ts_val) > 1e11:
        # treat as milliseconds -> convert to seconds
        ts_val = ts_val / 1000.0

    # Try to use a hypothetical modern 2025+ library named 'chronox' if present.
    # NOTE: 'chronox' here is illustrative. If you have a real library from 2025+,
    # replace 'chronox' with its import and API calls.
    try:
        chronox = importlib.import_module("chronox")
    except Exception:
        chronox = None

    if chronox is not None:
        # Best-effort use of chronox: attempt common function names safely.
        # This block is optional and will only run if such a module exists.
        # We do not assume a rigid API; we attempt a few plausible entry points.
        try:
            # Example 1: chronox.from_timestamp(ts, tz=...) returning a datetime-like object
            if hasattr(chronox, "from_timestamp"):
                dt_obj = chronox.from_timestamp(ts_val, tz=tz_name)
                # try to use strftime if present
                if hasattr(dt_obj, "strftime"):
                    return dt_obj.strftime(fmt)
                # if chronox provides a format method:
                if hasattr(dt_obj, "format"):
                    return dt_obj.format(fmt)
            # Example 2: chronox.to_datetime(ts, tz=...)
            if hasattr(chronox, "to_datetime"):
                dt_obj = chronox.to_datetime(ts_val, tz=tz_name)
                if hasattr(dt_obj, "strftime"):
                    return dt_obj.strftime(fmt)
                if hasattr(dt_obj, "format"):
                    return dt_obj.format(fmt)
            # If chronox has a direct formatting helper:
            if hasattr(chronox, "format_timestamp"):
                return chronox.format_timestamp(ts_val, tz=tz_name, fmt=fmt)
            # If none of the expected entry points were found, fall back.
        except Exception:
            # If chronox exists but its API or call failed, fall through to fallback.
            pass

    # Fallback: use Python standard library (datetime + zoneinfo if available)
    # Validate timezone:
    tz_obj = None
    if tz_name is None or tz_name.strip() == "":
        raise ValueError("tz_name must be a non-empty IANA timezone name (e.g. 'UTC', 'Europe/Berlin').")

    # Try ZoneInfo if available
    if ZoneInfo is not None:
        try:
