except Exception:
    HAS_SCIPY = False


def analyze_distribution(
    counts: Dict[str, int],
    top_n: Optional[int] = 5,
    significance: float = 0.05
) -> Dict[str, Any]:
    """
    Analyze uniformity of a categorical distribution and produce an introductory description.

    Parameters
    - counts: dict mapping category -> non-negative integer count (must not be empty)
    - top_n: optional number of top categories to list in the description (default 5)
    - significance: significance level for chi-square uniformity test (default 0.05)

    Returns:
    A dictionary containing:
    - counts: original dict
    - total: total count
