    # Interpret normalized entropy and Gini with simple thresholds
    def _interpret_uniformity(norm_ent: float, gini_val: float, jsd: float) -> str:
        if norm_ent >= 0.92 and gini_val <= 0.08 and jsd <= 0.02:
