    This is a best-effort that handles quotes and escapes (single/double).
    """
    start = s.find("{")
    if start == -1:
        return None
    depth = 0
    i = start
    in_string = False
    string_char = ""
    escape = False
    while i < len(s):
        ch = s[i]
        if in_string:
            if escape:
                escape = False
            elif ch == "\\":
                escape = True
            elif ch == string_char:
                in_string = False
        else:
            if ch == '"' or ch == "'":
                in_string = True
                string_char = ch
            elif ch == "{":
                depth += 1
